export interface LocaleFormats {
  LOCALE: string;

  DATETIME_FORMATS: {
    medium: string,
    mediumDateText: string,
    shortDateText: string,
    mediumDate: string,
    // mediumTime supports only these 2 strings: 'HH:mm:ss' and 'hh:mm:ss a'
    mediumTime: string,
    // shortTime supports only these 2 strings: 'HH:mm' and 'hh:mm a'
    shortTime: string,
    short: string,
    shortDate: string
  };

  NUMBER_FORMATS: {
    DECIMAL_SEP: string,
    number_regex: string,
    CURRENCY_SYM: string,
    GROUP_SEP: string,
    number_format: string
  };
}